Axiom functional_extensionality : forall {X Y: Type}
                                    {f g : X -> Y},
  (forall (x:X), f x = g x) -> f = g.

Ltac permute_havoc st :=
  apply E_Seq with st; 
    try apply E_Havoc;
    try (rewrite t_update_permute; 
      [apply E_Havoc | intro contra; discriminate ]).

Theorem optimize_0plus_b_sound : forall b,
  beval (optimize_0plus_b b) = beval b.
Proof.
  intro b. 
  induction b; 
  try (simpl; reflexivity);
  try (simpl; 
      rewrite (optimize_0plus_sound a1);
      rewrite (optimize_0plus_sound a2);
      reflexivity);
  try simpl.
  - rewrite IHb. reflexivity.
  - rewrite IHb1, IHb2. reflexivity.
Qed.

Theorem optimize_0times_sound : forall a,
  aeval (optimize_0times a) = aeval a.
Proof.
  intro a. 
  induction a; 
  try (simpl; rewrite IHa1, IHa2; reflexivity);
  try reflexivity.
  (* AMult case *)
  - destruct a1 eqn:Ea1; 
    try (simpl; simpl in IHa1; rewrite IHa1, IHa2;
        reflexivity).
    (* AMult case *)
    + destruct n eqn:En;
      [reflexivity | simpl; rewrite IHa2; reflexivity].
Qed.
